const SECTABLE_LIQUIDITY = { moins100: 0, "100-500": 250000, "500-1000": 750000, plus1000: 1500000 };

function scoreJuridiction(j, answers) {
  let score = 0;
  const reasons = [];
  // Convention avec le pays d'origine (matrice réelle, 54 pays africains)
  const row = TREATY_MATRIX[answers.origine];
  if (row) {
    const idx = JUR_ORDER.indexOf(j.code);
    const status = row[idx];
    if (status === true) { score += 30; reasons.push("Convention en vigueur avec ce pays"); }
    else if (status === "S") { score += 5; reasons.push("Convention signée, pas encore en vigueur"); }
    else { reasons.push("Pas de convention avec ce pays — retenue à la source pleine à la source"); }
  }
  // Priorité choisie
  if (answers.priorite === "double-imposition" && row && row[JUR_ORDER.indexOf(j.code)] === true) score += 20;
  if (answers.priorite === "regime" && (j.code === "NL" || j.code === "LU" || j.code === "CY")) score += 20;
  if (answers.priorite === "cout" && (j.code === "CY" || j.code === "EE" || j.code === "CZ")) score += 20;
  if (answers.priorite === "reputation" && (j.code === "NL" || j.code === "LU" || j.code === "FR" || j.code === "DE")) score += 20;
  // Objectif : levée de fonds -> favorise réputation / hubs
  if (answers.objectif !== "circulation" && (j.code === "NL" || j.code === "FR" || j.code === "DE" || j.code === "UK")) score += 10;
  // Flux : rapatriement pur -> favorise faible frottement à la distribution
  if (answers.flux === "rapatriement" && j.code === "EE") score -= 10; // Estonie pénalise justement la distribution
  if (answers.flux === "reinvestissement" && j.code === "EE") score += 15;
  // Substance : structure petite (juste le fondateur) -> favorise substance faible
  if (answers.associes === "seul" && (j.substance === "faible" || j.substance === "faible-moyen")) score += 10;
  return { score, reasons };
}

// jsPDF n'est pas une librairie pré-disponible dans l'environnement d'aperçu
// Claude (contrairement à lucide-react) — on la charge dynamiquement via CDN,
// ce qui fonctionne aussi bien ici que sur un site déployé, sans que Denis
// ait besoin de l'ajouter comme dépendance npm.
let jsPDFPromise = null;
function loadJsPDF() {
  if (window.jspdf && window.jspdf.jsPDF) return Promise.resolve(window.jspdf.jsPDF);
  if (jsPDFPromise) return jsPDFPromise;
  jsPDFPromise = new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
    script.onload = () => resolve(window.jspdf.jsPDF);
    script.onerror = () => reject(new Error("Impossible de charger la librairie PDF"));
    document.head.appendChild(script);
  });
  return jsPDFPromise;
}

function stripMarkdownArtifacts(text) {
  if (!text) return text;
  return text
    .replace(/\*\*/g, "")
    .replace(/^[ \t]*[-*][ \t]+/gm, "")
    .replace(/\*/g, "");
}

